// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public {
        c = new ERCDDAToken(1000, "Test", "TST");
    }

    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0);
        vm.assume(burnAmount <= c.totalSupply());
        uint256 supplyBefore = c.totalSupply();
        vm.prank(c.owner());
        try c.burn(burnAmount) returns (bool) {
            uint256 supplyAfter = c.totalSupply();
            assertTrue(supplyAfter == supplyBefore - burnAmount);
        } catch {
            assertTrue(false, "burn should not revert");
        }
    }
}
